-- French comes from FR below (accents written as byte escapes so this file
-- stays plain ASCII). Language: /guilded lang en|fr|de|es|auto; "auto" (default)
-- follows frFR, deDE, esES or esMX; other clients use English. The tools window's buttons and labels (officer pages
-- too) go through ns.L by themselves (Minimap.lua's newButton / newLabel).
-- To add a translation, add a line to FR below.
