  ["Guilded only knows the materials of recipes you know yourself. Open the profession window, then try again."] = "Guilded kennt nur die Materialien deiner eigenen Rezepte. \195\150ffne das Berufsfenster und versuche es erneut.",
  ["Guilded read your %s recipes (%d). Your guild can now see who can craft what."] = "Guilded hat deine Rezepte f\195\188r %s gelesen (%d). Deine Gilde sieht nun, wer was herstellen kann.",
  ["Guilded saved %s's %s recipes (%d) from the window you opened."] = "Guilded hat die Rezepte von %s f\195\188r %s (%d) aus dem ge\195\182ffneten Fenster gespeichert.",
