  ["Ledger sync is off. Entries already received stay."] = "Kassenbuch-Sync ist aus. Bereits empfangene Eintr\195\164ge bleiben erhalten.",
  ["Ledger sync is on. Officers who turn it on share EP/GP entries in game; nothing is deleted."] = "Kassenbuch-Sync ist an. Offiziere, die ihn einschalten, teilen EP/GP-Eintr\195\164ge im Spiel; nichts wird gel\195\182scht.",
