  ["No gear check yet. Press Check my gear."] = "Noch kein Ausr\195\188stungscheck. Klicke auf Ausr\195\188stung pr\195\188fen.",
  ["No GP price is set for %s in %s. Set it on Discord (/core items), or run it with a price: /guilded council priority <GP> <item>."] = "F\195\188r %s in %s ist kein GP-Preis festgelegt. Lege ihn in Discord fest (/core items) oder starte mit einem Preis: /guilded council priority <GP> <item>.",
  ["No GP price is set for %s in %s. Set it with /guilded price <item> <GP> (or /core items on Discord), then drop it again."] = "Kein GP-Preis f\195\188r %s in %s festgelegt. Nutze /guilded price <item> <GP> (oder /core items in Discord) und lege den Gegenstand erneut ab.",
  ["No guild bank snapshot yet. Open the guild bank once (any tab) with Guilded on."] = "Noch kein Gildenbank-Datenstand. \195\150ffne die Gildenbank einmal (beliebiger Reiter) mit aktivem Guilded.",
