  ["No points yet. They come from Discord after an officer imports the runs."] = "Noch keine Punkte. Sie kommen von Discord, nachdem ein Offizier die L\195\164ufe importiert hat.",
  ["No profession cooldowns are known. They are read when you open a profession window."] = "Keine Berufsabklingzeiten bekannt. Sie werden beim \195\150ffnen eines Berufsfensters gelesen.",
  ["No prospects yet. /guilded recruit add <name> [note]"] = "Noch keine Bewerber. /guilded recruit add <name> [note]",
  ["No public target for this route"] = "Keine \195\182ffentliche Zielzeit f\195\188r diese Route",
