  ["Imported That's My BiS priorities for %d item(s). Item tooltips show them."] = "Prioridades de That's My BiS importadas para %d objeto(s). Se muestran en las descripciones de los objetos.",
  ["Imported."] = "Importado.",
  ["In Discord, use /character pair, copy the /guilded verify line it shows and paste it here."] = "Usa /character pair en Discord, copia la l\195\173nea de /guilded verify que aparece y p\195\169gala aqu\195\173.",
  ["in the calendar"] = "en el calendario",
  ["In time"] = "Dentro de tiempo",
  ["In-game only (default)"] = "Solo en el juego (predeterminado)",
  ["In-game only selected. Your saved data and guild permissions are preserved."] = "Modo solo en el juego seleccionado. Se conservan tus datos y permisos de hermandad.",
  ["In-game only: gear checks, dungeon recording, raid attendance and loot tools work without Discord or signups. Officers can share local standings with online guildmates.\n\nConnected: optional companion sync adds Discord rosters, signups and verified season scores.\n\nData stays in SavedVariables. Keep backups. This choice preserves existing rosters and points; it does not stop a running companion. Change it any time with /guilded setup."] = "Solo en el juego: las revisiones de equipo, la grabaci\195\179n de mazmorras, la asistencia a bandas y las herramientas de bot\195\173n funcionan sin Discord ni inscripciones. Los oficiales pueden compartir clasificaciones locales con miembros conectados.\n\nConectado: la sincronizaci\195\179n opcional del compa\195\177ero a\195\177ade plantillas de Discord, inscripciones y puntuaciones de temporada verificadas.\n\nLos datos permanecen en SavedVariables. Guarda copias de seguridad. Esta elecci\195\179n conserva las plantillas y los puntos existentes; no detiene un compa\195\177ero en ejecuci\195\179n. C\195\161mbiala cuando quieras con /guilded setup.",
  ["Incoming map messages: %d, positions %d, ignored %d; last %s."] = "Mensajes de mapa recibidos: %d, posiciones %d, ignorados %d; \195\186ltimo %s.",
  ["Instances automatically mark you busy. Reports pause in combat. Location is never shared; Retail key sharing is optional."] = "Las instancias te marcan autom\195\161ticamente como ocupado. Los informes se pausan en combate. Nunca se comparte tu ubicaci\195\179n; compartir la piedra de Retail es opcional.",
  ["Intellect"] = "Intelecto",
  ["Invalid action, name or note (31 bytes maximum)."] = "Acci\195\179n, nombre o nota no v\195\161lidos (m\195\161ximo 31 bytes).",
  ["invalid coordinates"] = "coordenadas no v\195\161lidas",
  ["Invalid or oversized GRM archive."] = "Archivo GRM no v\195\161lido o demasiado grande.",
  ["invalid payload"] = "datos no v\195\161lidos",
  ["invited"] = "invitado",
  ["Issues"] = "Problemas",
  ["It checks by itself when a ready check starts: every Guilded reports what it carries. Hover a row for details; a question mark means the game hides it."] = "Se revisa autom\195\161ticamente al iniciar una comprobaci\195\179n de listos: cada Guilded informa de su equipo. Pasa el cursor por una fila para ver detalles; un signo de interrogaci\195\179n indica que el juego oculta los datos.",
